	@Test
	void scannedGetterFailureCannotStrandOwnedDelegate() {
		IllegalStateException failure = new IllegalStateException("scanned metadata failure");
		ReportingRecords records = new ReportingRecords(new long[] { 5, 2, 3 }, "scanned", failure, null);
		LmdbStatementAccessArbiter.RuntimeEvidence evidence = new LmdbStatementAccessArbiter.RuntimeEvidence();
		RecordingObserver observer = new RecordingObserver(null);
		RecordIterator measured = measured(records, evidence, observer);
		exhaust(measured);
		assertSame(failure, assertThrows(IllegalStateException.class, measured::close));
		// The existing API calls this getter before the try/finally that owns delegate close.
		assertThat(records.closes).as("the owned delegate closes even when its scanned getter throws").isEqualTo(1);
		assertAxes(measured, -1L, 2L, 3L);
		assertThat(observer.reports).containsExactly(new Report(2, 2, 3, false));
		measured.close();
		assertThat(records.closes).isEqualTo(1);
	}

	@ParameterizedTest
	@CsvSource({
			"index, false, false", "index, false, true", "index, true, false", "index, true, true",
			"scanned, false, false", "scanned, false, true", "scanned, true, false", "scanned, true, true",
			"matched, false, false", "matched, false, true", "matched, true, false", "matched, true, true",
			"filtered, false, false", "filtered, false, true", "filtered, true, false", "filtered, true, true"
	})
	void metadataFailureAlwaysClosesOwnedDelegateAndKeepsPrimaryFailure(String axis, boolean error,
			boolean closeFails) {
		Throwable metadataFailure = error ? new AssertionError("metadata " + axis)
				: new IllegalStateException("metadata " + axis);
		IllegalArgumentException closeFailure = new IllegalArgumentException("owned close");
		ReportingRecords records = new ReportingRecords(new long[] { 5, 2, 3 }, axis, metadataFailure,
				closeFails ? closeFailure : null);
		LmdbStatementAccessArbiter.RuntimeEvidence evidence = new LmdbStatementAccessArbiter.RuntimeEvidence();
		RecordingObserver observer = new RecordingObserver(null);
		RecordIterator measured = measured(records, evidence, observer);
		exhaust(measured);
		Throwable actual = assertThrows(metadataFailure.getClass(), measured::close);
		assertSame(metadataFailure, actual);
		assertThat(records.closes).as("metadata failure cannot strand the owned iterator").isEqualTo(1);
		if (closeFails) {
			assertThat(actual.getSuppressed()).containsExactly(closeFailure);
		} else {
			assertThat(actual.getSuppressed()).isEmpty();
		}
		assertAxes(measured, axis.equals("scanned") ? -1L : 5L,
				axis.equals("matched") ? -1L : 2L, axis.equals("filtered") ? -1L : 3L);
		assertThat(measured.getIndexName()).isEqualTo(axis.equals("index") ? "" : "spoc");
		assertThat(observer.reports).containsExactly(new Report(axis.equals("scanned") ? 2L : 5L, 2L, 3L, false));
		assertThat(evidence.completedCount(0)).isOne();
		measured.close();
		assertThat(records.closes).isEqualTo(1);
		assertThat(observer.reports).hasSize(1);
	}

	@ParameterizedTest
	@CsvSource({ "5, -1, 3", "-1, 2, -1", "5, 2, -1", "-1, -1, 3" })
	void mixedRawAxesRemainIndependentOfObserverFallback(long scanned, long matched, long filtered) {
		ReportingRecords records = new ReportingRecords(new long[] { scanned, matched, filtered }, null, null, null);
		LmdbStatementAccessArbiter.RuntimeEvidence evidence = new LmdbStatementAccessArbiter.RuntimeEvidence();
		RecordingObserver observer = new RecordingObserver(null);
		RecordIterator measured = measured(records, evidence, observer);
		assertAxes(measured, scanned, matched, filtered);
		exhaust(measured);
		measured.close();
		assertAxes(measured, scanned, matched, filtered);
		long actualScanned = scanned >= 0 ? scanned : 2L;
		long actualMatched = matched >= 0 ? matched : 2L;
		long actualFiltered = filtered >= 0 ? filtered : Math.max(0L, actualScanned - actualMatched);
		assertThat(observer.reports).containsExactly(new Report(actualScanned, actualMatched, actualFiltered, false));
		assertThat(records.closes).isEqualTo(1);
	}

